def group_by(items, key):
    """
    Group items into a dict of lists based on the result of key(item).
    Preserves the original order of items within each group.
    Does not mutate the input items.
    """
    groups = {}
    for item in items:
        k = key(item)
        groups.setdefault(k, []).append(item)
    return groups


